  ["Friend <img id=\"#115\" width=\"24\" height=\"24\" valign=\"0.5\"/> Signature Friend Signature Friend Signature"] = "Amigo <img id=\"#115\" width=\"24\" height=\"24\" valign=\"0.5\"/> Assinatura Assinatura do Amigo Assinatura do Amigo",
  ["Friend is not online; cannot initiate a voice call invitation."] = "Amigo não está online; não é possível iniciar um convite de chamada de voz.",
