  ["Curiosity"] = "Curiosidade",
  ["Curiosity killed the Cat, Lily."] = "A curiosidade matou o Gato, Lily.",
  ["Curious about the identity of the performer"] = "Curioso sobre a identidade do artista",
  ["Curious Nighthawk"] = "Curioso Vigia Noturno",
