  ["Enjoy\r\nyour freedom"] = "Aproveite\r\nsua liberdade",
  ["Enjoy the Tingen sunshine while you can; it might start raining again in a while."] = "Aproveite o sol de Tingen enquanto pode; pode começar a chover novamente daqui a pouco.",
  ["Get some good rest"] = "Descanse bem",
  ["Rest Well (Ending)"] = "Descanse bem (final)",
  ["Prepare well! The opportunity for you and me is coming..."] = "Prepare-se bem! A oportunidade para você e para mim está chegando...",
  ["Properly"] = "Apropriadamente",
  ["Alright, alright, we'll practice with towels when we get home."] = "Tudo bem, tudo bem, vamos praticar com toalhas quando chegarmos em casa.",
  ["Work hard, stop thinking nonsense, I will always treat you as my best friend."] = "Trabalhe duro, pare de pensar besteiras, sempre tratarei você como meu melhor amigo.",
  ["Squander your talent well."] = "Desperdice bem o seu talento.",
  ["So good-looking"] = "Tão bonito",
  ["So good-looking!"] = "Tão bonito!",
  ["Alright, alright, I get it—didn't you say to keep your voice down?"] = "Tudo bem, tudo bem, entendi - você não disse para manter a voz baixa?",
  ["Good Child"] = "Boa criança",
  ["Good boy, hurry and remember! Once you remember, they will let you go."] = "Bom menino, corra e lembre-se! Depois que você se lembrar, eles o deixarão ir.",
  ["What a coincidence, little gentleman selling newspapers, we meet again."] = "Que coincidência, senhorzinho vendedor de jornais, nos reencontramos.",
  ["Good Citizen Certificate"] = "Certificado de Bom Cidadão",
  ["So weak... they can't even handle this?"] = "Tão fracos... eles não conseguem nem lidar com isso?",
  ["Can a kind person help me catch the mice?"] = "Uma pessoa gentil pode me ajudar a pegar os ratos?",
  ["Kind person, I have one last question. Did we win in the end?"] = "Pessoa gentil, tenho uma última pergunta. Ganhamos no final?",
  ["Kind soul, please save the people trapped on the snowy mountain..."] = "Alma gentil, por favor salve as pessoas presas na montanha nevada...",
  ["Kind soul, spare some change..."] = "Alma gentil, poupe alguns trocos...",
  ["Kind advice"] = "Bom conselho",
  ["Kind Comfort"] = "Conforto gentil",
  ["Kind {Mr.{ Ms.|}}, please give a little more... there are still many children who have nothing to eat..."] = "Gentil {Sr.{Sra.|}}, por favor dê um pouco mais... ainda tem muita criança que não tem o que comer...",
  ["Kind {{Mr.|Ms.}}, if you like my dance, please go to the meat stall ahead and support my sister Mary Jane's business."] = "Gentil {{Sr.|Sra.}}, se você gosta da minha dança, por favor vá até a barraca de carne à frente e apoie os negócios da minha irmã Mary Jane.",
  ["Kind sir, can you give me a match..."] = "Gentil senhor, você pode me dar um fósforo...",
  ["Kind traveler, have you seen my son?"] = "Bom viajante, você viu meu filho?",
  ["Kind-hearted Lightning Lily, arriving at Water Lily Town in twenty-five minutes, is there some magic involved?"] = "O bondoso Lírio Relâmpago, chegando à Cidade dos Nenúfares em vinte e cinco minutos, há alguma magia envolvida?",
  ["Kind Flower Stall Owner"] = "Proprietário gentil de uma barraca de flores",
  ["So fast! Thank you, let me help you organize the packages."] = "Tão rápido! Obrigado, deixe-me ajudá-lo a organizar os pacotes.",
  ["I really want to become an adult..."] = "Eu realmente quero me tornar um adulto...",
  ["I really want to eat..."] = "Eu realmente quero comer...",
